// ---------------------------------------------------------------------------
// 0x001EE3F8 -- camp/battle row message dispatch.
//
// Argument registers: r0 = id, r1..r3 are forwarded to the final message
// helper, and the fifth argument (original [sp+0x48]) is a lookup gate.
//
//   * gate == 0: both record lookups and the u8 at battle-record +0xA4 are
//     skipped, so the row value is the raw signed id, the short count is zero
//     and the category stays 0x17.
//   * gate != 0 and id < 0: the row value is forced to zero and the lookups are
//     skipped as well.
//   * otherwise 0x002B9364 (camp node) and 0x002B087C (battle record) are
//     queried twice with the low 16 bits of the id.  Record byte +3 bit 0
//     selects category 0x23 and the signed word at +0x88; with that bit clear
//     the category is 0x17 and the value is the u16 at camp-node +0x90 plus
//     one.  A selected value >= 0x81 or a fallback value >= 0x266 aborts.
//   * The battle record's u8 at +0xA4 is the short count.
//
// After the second lookup 0x002A63F8(category, subindex) gates the tail.  The
// subindex is not simply the row value: it is the live r1 left by the lookup
// block (the raw id when the gate is zero, zero for a negative id, the selected
// signed word or the fallback u16+1 otherwise), which is why the two values are
// tracked separately.
//
// The row setter 0x002AEC20(*(u32*)0x00433158, category, value, 1) then either
// forwards to 0x00389FEC (set succeeded) or, when the set failed, uses the
// short count to choose 0x002BF558 (count > 0) or the id*1000 scaled
// 0x002AEC80.  The bundle pointer at 0x00433158 is reloaded for the 0x00389FEC
// call, so a setter that rewrites the slot is observed.
//
// The return register is not consumed by the recovered caller at 0x001A3744;
// the reconstruction still mirrors it: the battle-record pointer on the abort
// paths, zero on the null/empty-resource paths, and the final helper's result
// otherwise.
// ---------------------------------------------------------------------------
extern "C" u8* battle_record_002b087c(u32 index) __asm__("battle_func_002b087c");
extern "C" u32 camp_row_set_002aec20(u8* bundle, u32 category, u32 value,
                                      u32 enable) __asm__("ui_func_002aec20");
extern "C" u32 camp_message_00389fec(u8* bundle, u32 id, u32 mode, u32 value,
                                     u32 zero, u32 arg1, u32 arg2, u32 arg3)
    __asm__("func_00389fec");
extern "C" u32 camp_message_002bf558(u32 group, u32 category, u32 count,
                                     u32 arg1, u32 arg2, u32 arg3)
    __asm__("func_002bf558");
extern "C" u32 camp_message_002aec80(u32 group, u32 category, u32 value,
                                     u32 arg1, u32 arg2, u32 arg3)
    __asm__("script_vm_func_002aec80");

namespace {

constexpr u32 kCampCategory = 0x17;             // default resource category
constexpr u32 kBattleCategory = 0x23;           // category for flag-bit records
constexpr s32 kSelectedValueMax = 0x81;         // selected branch abort bound
constexpr s32 kFallbackValueMax = 0x266;        // fallback branch abort bound
constexpr u32 kBattleFlagByte = 0x03;           // u8, bit 0 is the selector
constexpr u32 kBattleSelectedValue = 0x88;      // s16
constexpr u32 kBattleShortCount = 0xA4;         // u8
constexpr u32 kCampValueCount = 0x90;           // u16, used as count + 1
constexpr u32 kBundleSlot = 0x00433158;         // u8* used by both tails
constexpr u32 kMessageGroup = 2;                // first argument of the tails
constexpr u32 kMillisecondScale = 1000;         // fallback value multiplier

} // namespace

// DECOMP_FUNC(0x001ee3f8, 428)
extern "C" u32 camp_func_001ee3f8(s32 id, u32 arg1, u32 arg2, u32 arg3,
                                  u32 gate) {
    s32 value = id;                            // original r4
    u32 short_count = 0;                       // original r8
    u32 category = kCampCategory;              // original fp

    // 0x001EE41C..0x001EE480: first lookup block.  The battle lookup is issued
    // even when the camp lookup returns null; the null test happens afterwards.
    if (gate != 0) {
        if (id < 0) {
            value = 0;
        } else {
            const u8* const node = camp_node_002b9364(static_cast<u16>(id));
            const u8* const record =
                battle_record_002b087c(static_cast<u16>(id));
            if (node == nullptr) {
                return reinterpret_cast<u32>(record);
            }
            if ((record[kBattleFlagByte] & 1u) != 0) {
                value = *reinterpret_cast<const s16*>(
                    record + kBattleSelectedValue);
                category = kBattleCategory;
                if (value >= kSelectedValueMax) {
                    return reinterpret_cast<u32>(record);
                }
            } else {
                value = static_cast<s32>(*reinterpret_cast<const u16*>(
                            node + kCampValueCount)) +
                        1;
                if (value >= kFallbackValueMax) {
                    return reinterpret_cast<u32>(record);
                }
            }
            short_count = record[kBattleShortCount];
        }
    }

    // 0x001EE484..0x001EE4EC: second lookup block.  r1 is seeded with the raw
    // id before the gate is tested, so the gate-zero path forwards a negative
    // id unchanged even though a negative id otherwise maps to zero.
    u32 subindex = static_cast<u32>(id);       // original r1
    u32 check_category = kCampCategory;        // original sl

    if (gate != 0) {
        if (id < 0) {
            subindex = 0;
        } else {
            const u8* const node = camp_node_002b9364(static_cast<u16>(id));
            if (node == nullptr) {
                return 0;
            }
            // The second block tests the camp node before issuing the battle
            // lookup; the first block issues both lookups up front.
            const u8* const record =
                battle_record_002b087c(static_cast<u16>(id));
            if ((record[kBattleFlagByte] & 1u) != 0) {
                subindex = static_cast<u32>(static_cast<s32>(
                    *reinterpret_cast<const s16*>(
                        record + kBattleSelectedValue)));
                check_category = kBattleCategory;
                if (static_cast<s32>(subindex) >= kSelectedValueMax) {
                    return reinterpret_cast<u32>(record);
                }
            } else {
                subindex = static_cast<u32>(*reinterpret_cast<const u16*>(
                                node + kCampValueCount)) +
                            1;
                if (static_cast<s32>(subindex) >= kFallbackValueMax) {
                    // The second block loads the bound into r0, so this abort
                    // returns 0x266 rather than the battle-record pointer.
                    return static_cast<u32>(kFallbackValueMax);
                }
            }
        }
    }

    // 0x001EE4F0: 0x002A63F8(category, subindex).
    if (ui_func_002a63f8(check_category, subindex) == 0) {
        return 0;
    }

    // 0x001EE504..0x001EE544: row setter and the two mutually exclusive tails.
    u8* const bundle =
        *reinterpret_cast<u8* const*>(static_cast<u32>(kBundleSlot));
    if (camp_row_set_002aec20(bundle, category, static_cast<u32>(value), 1) ==
        0) {
        if (static_cast<s32>(short_count) <= 0) {
            return camp_message_002aec80(
                kMessageGroup, category,
                static_cast<u32>(value) * kMillisecondScale, arg1, arg2, arg3);
        }
        return camp_message_002bf558(kMessageGroup, category, short_count, arg1,
                                     arg2, arg3);
    }

    u8* const reloaded_bundle =
        *reinterpret_cast<u8* const*>(static_cast<u32>(kBundleSlot));
    return camp_message_00389fec(reloaded_bundle, static_cast<u32>(id),
                                 kMessageGroup, static_cast<u32>(value), 0,
                                 arg1, arg2, arg3);
}

// ---------------------------------------------------------------------------
// 0x001F4E2C -- camp-work gate.
//
// [object+0x3064] is a signed camp phase.  A negative phase aborts with 0 and
// leaves both caller outputs untouched.  Otherwise the 64-bit outputs are
// cleared, the camp work base is fetched through 0x002A8A08, and the phase is
// reloaded (that fetch may publish a new phase).
//   * phase == 0x270F: accumulate a 64-bit flag mask.  [object+0x345C] adds
//     one; [object+0x345D..0x345F] gate three work bytes at +0x9108..+0x910A,
//     each contributing 1 << (byte + 1) as a sign-extended 32-bit value.
//   * phase == 0: store 1.
//   * phase > 0: replace the mask with the same shifted byte read from
//     work+0x9107+phase.
// Every path then lets 0x0028CDE4 fill two pre-zeroed s16 stack slots from the
// object; the second slot (the original's sp+0) is sign-extended into the
// second 64-bit output and the function returns 1.
//
// The two output pointers are assumed not to alias the object or the camp work
// base; aliasing would observe the original's intermediate 64-bit stores.
// ---------------------------------------------------------------------------
namespace {

constexpr u32 kCampPhaseOffset = 0x3064;   // s32 phase word in the object
constexpr s32 kCampPhaseComplete = 0x270F; // completed-phase sentinel (9999)
constexpr u32 kCampFlagA = 0x345C;         // u8 gates at 0x345C..0x345F
constexpr u32 kCampFlagB = 0x345D;
constexpr u32 kCampFlagC = 0x345E;
constexpr u32 kCampFlagD = 0x345F;
constexpr u32 kCampPhaseRow = 0x9107;      // u8 row indexed by the phase
constexpr u32 kCampEntryB = 0x9108;        // three fixed u8 entries
constexpr u32 kCampEntryC = 0x9109;
constexpr u32 kCampEntryD = 0x910A;

// 0x002A8A08 is `return *(u32*)0x0043E2A8[1] + 0x8C;`: it reads no argument
// register.  The original nonetheless leaves the entry phase in r0, the flag
// output pointer in r1 and zero in r2/r3, so the declaration carries those
// values and the call reproduces the original register image.
using CampGetWorkFn = u8* (*)(s32 entry_phase, u64* flag_mask, u32 zero);

// 0x0028CDE4(object, r1, r2) writes one s16 through each output pointer and
// reads only r0.  The original passes r1 = sp + 4 and r2 = sp, both pre-zeroed;
// only the r2 slot is consumed below.
using CampFillResultFn = void (*)(u8* object, s16* aux, s16* value);

// ARM `lsl` by a register uses the low byte of the count and yields zero for
// counts of 32 or more; the following `asr #31` sign-extends the 32-bit result.
// The pair therefore adds (s64)(s32)(1u << ((byte + 1) & 0xFF)).
inline u64 ShiftedFlagValue(u8 encoded) {
    const u32 shift = (static_cast<u32>(encoded) + 1u) & 0xFFu;
    const u32 value = shift < 32u ? (1u << shift) : 0u;
    return static_cast<u64>(static_cast<s64>(static_cast<s32>(value)));
}

} // namespace

// DECOMP_FUNC(0x001f4e2c, 408)
extern "C" s32 camp_func_001f4e2c(u8* object, u64* flag_mask, s64* result) {
    // 0x001F4E3C..0x001F4E50: signed entry gate.
    const s32 entry_phase =
        *reinterpret_cast<const s32*>(object + kCampPhaseOffset);
    if (entry_phase < 0) {
        return 0;
    }

    // 0x001F4E54..0x001F4E64: 64-bit clear of the first output, two 32-bit
    // clears of the second.
    *flag_mask = 0;
    *reinterpret_cast<u32*>(result) = 0;
    *reinterpret_cast<u32*>(reinterpret_cast<u8*>(result) + 4) = 0;

    // 0x001F4E68: camp work base.  The callee ignores the argument registers;
    // they are passed to keep the original call image.
    u8* const camp = reinterpret_cast<CampGetWorkFn>(camp_func_002a8a08)(
        entry_phase, flag_mask, 0);

    // 0x001F4E6C: reload after the fetch.
    const s32 phase =
        *reinterpret_cast<const s32*>(object + kCampPhaseOffset);

    if (phase == kCampPhaseComplete) {
        if (object[kCampFlagA] != 0) {
            *flag_mask = *flag_mask + 1u;
        }
        if (object[kCampFlagB] != 0) {
            *flag_mask = *flag_mask + ShiftedFlagValue(camp[kCampEntryB]);
        }
        if (object[kCampFlagC] != 0) {
            *flag_mask = *flag_mask + ShiftedFlagValue(camp[kCampEntryC]);
        }
        if (object[kCampFlagD] != 0) {
            *flag_mask = *flag_mask + ShiftedFlagValue(camp[kCampEntryD]);
        }
    } else if (phase == 0) {
        *flag_mask = 1;
    } else if (phase > 0) {
        *flag_mask =
            ShiftedFlagValue(camp[kCampPhaseRow + static_cast<u32>(phase)]);
    }

    // 0x001F4F78..0x001F4F9C: the helper may write either s16 slot; only the
    // value written through r2 (sp+0) is sign-extended into the output.
    s16 aux = 0;
    s16 value = 0;
    reinterpret_cast<CampFillResultFn>(camp_func_0028cde4)(object, &aux, &value);
    *result = static_cast<s64>(value);
    return 1;
}

// ---------------------------------------------------------------------------
// 0x001F8D04 -- draw one randomised group of entries for a script record.
//
// Sole direct caller: 0x001E5840 inside script_vm_func_001e5448 (0x001E5448).
//   r0  id     signed 16-bit record id (the caller loads `ldrsh [record+0x24]`)
//   r1  ids    u32[] output buffer (r8); written only when non-null
//   r2  flags  u8[] output buffer (fp); written unconditionally
//   r3  count  u32* output word (r6); written only when non-null
//   ->  r0     the 0..100 roll value, or 0 when nothing was produced
//
// Flow:
//   * resolve the 24-byte record through the owner at 0x00433158; when the
//     lookup fails, index the payload of TBB sub-table 0x21/0 directly
//     (payload + id*24, no bounds check beyond the row count);
//   * derive a target count from the record's byte pair +4/+5 (min/max, equal
//     pair means count = the pair and a fixed 50 roll);
//   * walk the three {u16 id, u8 mode, u8 chance} slots at +0x08/+0x0C/+0x10
//     and add every slot that passes the mode/chance gates;
//   * resolve the same record again, collect the camp rows 951..1150 whose
//     byte +0x24 lies in the record's +6/+7 band and whose byte +0x25 matches
//     one of the four accepted keys at +0x14..+0x17, then pick uniform random
//     rows from that stack list until the target count is reached.
//
// The "abort" path at 0x001F8FE8 performs a discarded table-slot read of index
// 0 (0x002C583C) before returning 0; the call is preserved.
// ---------------------------------------------------------------------------
namespace {

// 24-byte record returned by 0x00389E54.  The same shape is read out of the
// 0x002C0EC4 table-0x21 payload, whose stride is 24 bytes (0x001F8D34/0x001F8E00
// scale the id by three and then by eight).
struct ScriptDrawSlot {
    u16 id;      // +0x00: 0 disables the slot
    u8 mode;     // +0x02: must be 0 for the slot to roll
    u8 chance;   // +0x03: 1..255 threshold, 0 disables the slot
};

struct ScriptDrawRecord {
    u8 unused_00[4];    // +0x00..+0x03: never read by this body
    u8 count_min;       // +0x04
    u8 count_max;       // +0x05
    u8 scan_min;        // +0x06: lower bound of camp row +0x24
    u8 scan_max;        // +0x07: upper bound of camp row +0x24
    ScriptDrawSlot slots[3];  // +0x08, +0x0C, +0x10
    u8 accept[4];       // +0x14..+0x17: accepted camp row +0x25 values
};

static_assert(sizeof(ScriptDrawSlot) == 4);
static_assert(sizeof(ScriptDrawRecord) == 24);

// Minimal view of the row returned by 0x00256A50 (only the three fields this
// body touches; the row itself is much larger and opaque here).
struct CampScanRow {
    u8 unused_00[0x20];
    u16 value;          // +0x20: copied into the local candidate list
    u8 unused_22[2];
    u8 band;            // +0x24: compared against the record's +6/+7 band
    u8 key;             // +0x25: compared against the record's four accept bytes
};

static_assert(sizeof(CampScanRow) == 0x26);

constexpr u32 kScriptOwnerSlot = 0x00433158;  // *(void**) = 0x00389E54 owner
constexpr u32 kFallbackSlotId = 0x21;         // Tbb_GetGlobalSubTable(0x21, 0)
constexpr u32 kFallbackTableIndex = 0;
constexpr u32 kCampScanFirst = 0x3B7;         // literal at 0x001F9000
constexpr u32 kCampScanLast = 0x47E;          // literal at 0x001F9004
constexpr u32 kCampScanCount = kCampScanLast - kCampScanFirst + 1;
constexpr u32 kItemRollRange = 99;            // `mov r0,#0x63`; draw is 0..99
constexpr u32 kEqualCountRoll = 50;           // `moveq r0,#0x32`

using ScriptLookupFn = const ScriptDrawRecord* (*)(void* owner, s32 id);
using GlobalSubTableFn = const void* (*)(u32 slot_id, u32 table_index);
using PayloadDataFn = const void* (*)(const void* table);
using RowCountFn = u32 (*)(const void* table);
using RandomRangeFn = u32 (*)(u32 range_plus_one);
using DivideModFn = u64 (*)(u32 numerator, u32 denominator);
using AddItemFn = void (*)(s32 item, s32 flag);
using CampRowFn = const CampScanRow* (*)(u32 index);
using FlagTestFn = u32 (*)(s32 id);
using TableEntryFn = u32 (*)(u32 index);

// Both fallback sites (0x001F8DD4 and 0x001F8FB0) perform the same three calls
// in the same order and index the table-0x21 payload with payload + (3*id)*8.
// They differ only in what the caller does with a null result: the first one
// returns 0, the second one dereferences it.
const ScriptDrawRecord* FallbackRecord(u32 id, u32 triple) {
    const GlobalSubTableFn sub_table =
        reinterpret_cast<GlobalSubTableFn>(Tbb_GetGlobalSubTable);
    const PayloadDataFn payload_of =
        reinterpret_cast<PayloadDataFn>(Tbb_GetPayloadData);
    const RowCountFn row_count_of =
        reinterpret_cast<RowCountFn>(Tbb_GetRowCount);

    const void* const table = sub_table(kFallbackSlotId, kFallbackTableIndex);
    const u8* const payload = static_cast<const u8*>(payload_of(table));
    const u32 rows = row_count_of(table);
    if (id >= rows) {
        return nullptr;
    }
    return reinterpret_cast<const ScriptDrawRecord*>(payload + triple * 8u);
}

} // namespace

// DECOMP_FUNC(0x001f8d04, 796)
extern "C" u32 script_vm_func_001f8d04(s32 id, u32* ids, u8* flags,
                                        u32* count) {
    const ScriptLookupFn lookup =
        reinterpret_cast<ScriptLookupFn>(script_vm_func_00389e54);
    const RandomRangeFn random_range =
        reinterpret_cast<RandomRangeFn>(engine_func_002c0bcc);
    const DivideModFn divide =
        reinterpret_cast<DivideModFn>(ui_func_002c615c);
    const AddItemFn add_item =
        reinterpret_cast<AddItemFn>(script_vm_func_00295cbc);
    const CampRowFn camp_row =
        reinterpret_cast<CampRowFn>(camp_func_00256a50);
    const FlagTestFn flag_test =
        reinterpret_cast<FlagTestFn>(script_vm_func_0025b920);
    const TableEntryFn table_entry =
        reinterpret_cast<TableEntryFn>(engine_func_002c583c);

    // 0x001F8D18..0x001F8D3C: resolve the record through the shared owner, and
    // pre-scale the id for the table-0x21 fallback (3*id, then *8 = id*24).
    const ScriptDrawRecord* record =
        lookup(*reinterpret_cast<void**>(kScriptOwnerSlot), id);
    const u32 triple = static_cast<u32>(id) * 3u;
    if (record == nullptr) {
        record = FallbackRecord(static_cast<u32>(id), triple);
    }
    if (record == nullptr) {
        table_entry(0);  // 0x001F8FEC: discarded slot-0 table read
        return 0;
    }

    // 0x001F8D48..0x001F8D94: order the count pair and derive the target.
    u32 count_min = record->count_min;
    u32 count_max = record->count_max;
    if (count_max < count_min) {
        const u32 swap = count_min;
        count_min = count_max;
        count_max = swap;
    }

    u32 roll_value;
    u32 target;
    if (count_min == count_max) {
        // `moveq r0,#0x32`: an equal pair skips the draw entirely.
        roll_value = kEqualCountRoll;
        target = count_min;
    } else {
        const u32 span = count_max - count_min;
        const u32 draw = random_range(span);  // 0x002C0BCC, returns 0..span
        // 0x002C615C is the ARM unsigned divmod: only the quotient is kept.
        roll_value = static_cast<u32>(divide(draw * 100u, span));
        target = count_min + draw;
    }

    // 0x001F8D98..0x001F8DA8: a zero target aborts before any output.
    if (static_cast<s32>(target) <= 0) {
        table_entry(0);
        return 0;
    }
    if (count != nullptr) {
        *count = target;
    }

    // 0x001F8DAC..0x001F8E50: the three fixed slots.
    u32 produced = 0;
    for (u32 slot = 0; slot < 3; ++slot) {
        const ScriptDrawSlot& candidate = record->slots[slot];
        if (candidate.id == 0) {
            continue;
        }
        if (candidate.chance == 0) {
            continue;
        }
        if (candidate.mode != 0) {
            continue;
        }
        // 0x001F8E10..0x001F8E24: draw 0..99 and test `draw + 1 > chance`.
        const u32 roll = random_range(kItemRollRange);
        if (static_cast<u16>(roll + 1u) > candidate.chance) {
            continue;
        }
        add_item(static_cast<s32>(candidate.id), 1);
        if (ids != nullptr) {
            ids[produced] = candidate.id;
        }
        ++produced;
        if (static_cast<s32>(produced) >= static_cast<s32>(target)) {
            return roll_value;
        }
    }

    // 0x001F8E54..0x001F8E74: resolve the same record a second time.  The
    // original also stores the (still current) SP in its frame here for the
    // candidate list below; that is a private stack slot and has no effect.
    const ScriptDrawRecord* filter =
        lookup(*reinterpret_cast<void**>(kScriptOwnerSlot), id);
    if (filter == nullptr) {
        // 0x001F8FB0..0x001F8FE4: unlike the first site this result is used
        // without a null test, so a null pointer faults exactly as it does in
        // the original.
        filter = FallbackRecord(static_cast<u32>(id), triple);
    }

    // 0x001F8E78..0x001F8EAC: accepted keys and the camp row band.
    const u32 accept0 = filter->accept[0];
    u32 band_low = filter->scan_min;
    u32 band_high = filter->scan_max;
    const u32 accept1 = filter->accept[1];
    const u32 accept2 = filter->accept[2];
    const u32 accept3 = filter->accept[3];
    if (band_high < band_low) {
        const u32 swap = band_low;
        band_low = band_high;
        band_high = swap;
    }

    // 0x001F8EB8..0x001F8F38: collect the matching camp rows.  The bound is
    // unsigned and inclusive at both ends (0x3B7..0x47E); a null row is skipped.
    u16 matches[kCampScanCount];
    u32 match_count = 0;
    for (u32 index = kCampScanFirst; index <= kCampScanLast; ++index) {
        const CampScanRow* const row = camp_row(index);
        if (row == nullptr) {
            continue;
        }
        if (band_low > row->band) {
            continue;
        }
        if (row->band > band_high) {
            continue;
        }
        const u32 key = row->key;
        if (key != accept0 && key != accept1 && key != accept2 &&
            key != accept3) {
            continue;
        }
        matches[match_count] = row->value;
        ++match_count;
    }

    // 0x001F8F3C..0x001F8F4C
    const s16 match_total = static_cast<s16>(match_count);
    if (match_total == 0) {
        table_entry(0);
        return 0;
    }
    // Retained verbatim: with the guards above this is unreachable, exactly as
    // in the original.
    if (static_cast<s32>(target) <= static_cast<s32>(produced)) {
        return roll_value;
    }

    // 0x001F8F50..0x001F8FA0: pick uniformly from the collected rows.  The
    // draw bound is computed once (match_total - 1) and reused every pass.
    const u32 pick_range = static_cast<u32>(static_cast<u16>(match_total)) - 1u;
    do {
        const u32 draw = random_range(pick_range);
        const s16 picked = static_cast<s16>(matches[draw]);
        if (flag_test(static_cast<s32>(picked)) == 0) {
            flags[produced] = 1;
        } else {
            flags[produced] = 0;
        }
        add_item(static_cast<s32>(picked), 1);
        if (ids != nullptr) {
            ids[produced] = static_cast<u32>(static_cast<s32>(picked));
        }
        ++produced;
    } while (static_cast<s32>(produced) < static_cast<s32>(target));

    return roll_value;
}

// The ledger's 796-byte range for 0x001F8D04 also covers the 24-byte tail stub
// at 0x001F9008 (mov r0,#0xA; vldr s4,[..]; vldr s3,[..]; b 0x002568F4 with the
// 20.0f/5.0f constants).  It is not part of this routine and is reached only by
// the raw `b` at 0x0025C058, so its bytes are preserved verbatim.
asm(
    ".text\n"
    ".word 0xe3a0000a\n"   // 0x001F9008: mov r0, #0xa
    ".word 0xed9f2a01\n"   // 0x001F900C: vldr s4, [pc, #4]
    ".word 0xeddf1a01\n"   // 0x001F9010: vldr s3, [pc, #4]
    ".word 0xea017636\n"   // 0x001F9014: b 0x002568F4
    ".word 0x41a00000\n"   // 0x001F9018: 20.0f
    ".word 0x40a00000\n"   // 0x001F901C: 5.0f
);

